vec3 roundedBoxSdg(vec2 p, vec2 halfSize, float radius) {
    vec2 q = abs(p) - halfSize + radius;
    float g = max(q.x, q.y);
    vec2 qm = max(q, 0.0);
    float l = length(qm);
    float d = (g > 0.0) ? l - radius : g - radius;
    vec2 s = sign(p);
    vec2 n = (l > 1e-6) ? s * (qm / l) : s * ((q.x > q.y) ? vec2(1.0, 0.0) : vec2(0.0, 1.0));
